#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE=.production-setup.env

put_ssm_secret() (
  local name="$1" value="$2" secret_file
  secret_file=$(mktemp)
  chmod 0600 "$secret_file"
  trap 'rm -f "$secret_file"' EXIT
  printf '%s' "$value" | python3 -c 'import json,sys; print(json.dumps({"Name":sys.argv[1],"Type":"SecureString","Tier":"Standard","Value":sys.stdin.read()}))' "$name" > "$secret_file"
  aws ssm put-parameter --region "$AWS_REGION" --cli-input-json "file://$secret_file" >/dev/null
  say "Stored $name in Parameter Store."
)

parameter_exists() {
  aws ssm get-parameter --region "$AWS_REGION" --name "$1" --query Parameter.Name --output text >/dev/null 2>&1
}

banner "Johnny production v1 setup"

stage "AWS account and domain"
say "Use an AWS account with a Route 53 hosted zone for the production domain."
open_url "https://console.aws.amazon.com/route53/v2/hostedzones"
step "Copy the domain and its hosted zone ID."
AWS_REGION=ap-northeast-1
say "AWS region: $AWS_REGION (Tokyo)."
ask DOMAIN_NAME "Production domain (for example, example.com):"
ask ROUTE53_ZONE_ID "Route 53 hosted zone ID:"
ask CERTIFICATE_EMAIL "Email for API TLS certificate notices:"
ask GOOGLE_OAUTH_CLIENT_ID "Google OAuth client ID:"
ask LLM_MODEL "Approved model name:"
ask GITHUB_REPOSITORY "GitHub owner/repo:"
for key in AWS_REGION DOMAIN_NAME ROUTE53_ZONE_ID CERTIFICATE_EMAIL GOOGLE_OAUTH_CLIENT_ID LLM_MODEL GITHUB_REPOSITORY; do
  [[ -n "${!key}" ]] || { warn "$key is required"; exit 1; }
  write_env "$key" "${!key}"
done
command -v gh >/dev/null || { warn "Install and authenticate GitHub CLI before continuing."; exit 1; }
[[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner)" = "$GITHUB_REPOSITORY" ]] || { warn "Current checkout does not match $GITHUB_REPOSITORY"; exit 1; }
aws sts get-caller-identity --query Account --output text >/dev/null
if _existing GITHUB_OIDC_PROVIDER_ARN >/dev/null; then
  GITHUB_OIDC_PROVIDER_ARN=$(_existing GITHUB_OIDC_PROVIDER_ARN)
else
  GITHUB_OIDC_PROVIDER_ARN=""
  for provider_arn in $(aws iam list-open-id-connect-providers --query 'OpenIDConnectProviderList[].Arn' --output text); do
    provider_url=$(aws iam get-open-id-connect-provider --open-id-connect-provider-arn "$provider_arn" --query Url --output text)
    if [[ "$provider_url" = "token.actions.githubusercontent.com" ]]; then
      provider_audiences=$(aws iam get-open-id-connect-provider --open-id-connect-provider-arn "$provider_arn" --query 'ClientIDList[]' --output text)
      [[ " $provider_audiences " = *" sts.amazonaws.com "* ]] || { warn "Existing GitHub OIDC provider must allow sts.amazonaws.com"; exit 1; }
      GITHUB_OIDC_PROVIDER_ARN="$provider_arn"
      break
    fi
  done
fi
write_env GITHUB_OIDC_PROVIDER_ARN "$GITHUB_OIDC_PROVIDER_ARN"

stage "Terraform state bucket"
AWS_ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
STATE_BUCKET="johnny-production-terraform-state-$AWS_ACCOUNT_ID-$AWS_REGION"
say "State bucket: $STATE_BUCKET"
if ! aws s3api head-bucket --bucket "$STATE_BUCKET" >/dev/null 2>&1; then
  confirm "Create the private Terraform state bucket?" || exit 1
  aws s3api create-bucket --bucket "$STATE_BUCKET" --region "$AWS_REGION" --create-bucket-configuration "LocationConstraint=$AWS_REGION" >/dev/null
fi
aws s3api put-public-access-block --bucket "$STATE_BUCKET" --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
aws s3api put-bucket-encryption --bucket "$STATE_BUCKET" --server-side-encryption-configuration '{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"}}]}'
install -d -m 0700 infra/terraform/environments/production
cat > infra/terraform/environments/production/backend.hcl <<EOF
bucket       = "$STATE_BUCKET"
key          = "johnny/production/terraform.tfstate"
region       = "$AWS_REGION"
encrypt      = true
use_lockfile = true
EOF
write_env STATE_BUCKET "$STATE_BUCKET"

stage "Review and provision infrastructure"
command -v terraform >/dev/null || { warn "Install Terraform 1.10 or later, then rerun this wizard."; exit 1; }
python3 - <<'PY'
import json
from pathlib import Path
values = dict(line.split('=', 1) for line in Path('.production-setup.env').read_text().splitlines() if line and not line.startswith('#'))
names = ['aws_region', 'domain_name', 'route53_zone_id', 'certificate_email', 'google_oauth_client_id', 'llm_model', 'github_repository']
settings = {name: values[name.upper()] for name in names}
settings['github_oidc_provider_arn'] = values.get('GITHUB_OIDC_PROVIDER_ARN', '')
Path('infra/terraform/environments/production/terraform.tfvars.json').write_text(json.dumps(settings, indent=2))
PY
terraform -chdir=infra/terraform init -backend-config=environments/production/backend.hcl
terraform -chdir=infra/terraform plan -var-file=environments/production/terraform.tfvars.json -out=production.tfplan
confirm "Apply the reviewed production Terraform plan and start AWS billing?" || exit 1
terraform -chdir=infra/terraform apply production.tfplan

stage "Store backend secrets"
say "These values go to Parameter Store, never to GitHub or Terraform state."
if ! parameter_exists /johnny/production/database-password; then
  DB_PASSWORD=$(python3 -c 'import secrets; print(secrets.token_urlsafe(32))')
  put_ssm_secret /johnny/production/database-password "$DB_PASSWORD"
  unset DB_PASSWORD
else say "Database password already exists; keeping it."; fi
if ! parameter_exists /johnny/production/garmin-credential-master-key; then
  GARMIN_KEY=$(python3 -c 'import base64,os; print(base64.urlsafe_b64encode(os.urandom(32)).decode())')
  put_ssm_secret /johnny/production/garmin-credential-master-key "$GARMIN_KEY"
  unset GARMIN_KEY
else say "Garmin encryption key already exists; keeping it."; fi
if ! parameter_exists /johnny/production/admin-token; then
  ADMIN_TOKEN=$(python3 -c 'import secrets; print(secrets.token_urlsafe(32))')
  put_ssm_secret /johnny/production/admin-token "$ADMIN_TOKEN"
  unset ADMIN_TOKEN
else say "Admin token already exists; keeping it."; fi
if ! parameter_exists /johnny/production/openai-api-key; then
  open_url "https://platform.openai.com/api-keys"
  ask_secret OPENAI_API_KEY "Paste the OpenAI API key:"
  [[ -n "$OPENAI_API_KEY" ]] || exit 1
  put_ssm_secret /johnny/production/openai-api-key "$OPENAI_API_KEY"
  unset OPENAI_API_KEY
else say "OpenAI key already exists; keeping it."; fi
if ! parameter_exists /johnny/production/google-oauth-client-secret; then
  open_url "https://console.cloud.google.com/apis/credentials"
  ask_secret GOOGLE_CLIENT_SECRET "Paste the Google OAuth client secret:"
  [[ -n "$GOOGLE_CLIENT_SECRET" ]] || exit 1
  put_ssm_secret /johnny/production/google-oauth-client-secret "$GOOGLE_CLIENT_SECRET"
  unset GOOGLE_CLIENT_SECRET
else say "Google OAuth client secret already exists; keeping it."; fi

stage "Connect GitHub Actions"
open_url "https://github.com/$GITHUB_REPOSITORY/settings/environments"
step "Create a production environment and restrict deployments to the main branch."
pause "Press Enter after the production environment exists."
set_var AWS_REGION "$AWS_REGION"
set_var AWS_BUILD_ROLE_ARN "$(terraform -chdir=infra/terraform output -raw github_build_role_arn)"
set_var AWS_DEPLOY_ROLE_ARN "$(terraform -chdir=infra/terraform output -raw github_deploy_role_arn)"
set_var AWS_TERRAFORM_PLAN_ROLE_ARN "$(terraform -chdir=infra/terraform output -raw github_terraform_plan_role_arn)"
set_var STATE_BUCKET "$STATE_BUCKET"
set_var DOMAIN_NAME "$DOMAIN_NAME"
set_var ROUTE53_ZONE_ID "$ROUTE53_ZONE_ID"
set_var CERTIFICATE_EMAIL "$CERTIFICATE_EMAIL"
set_var GOOGLE_OAUTH_CLIENT_ID "$GOOGLE_OAUTH_CLIENT_ID"
set_var LLM_MODEL "$LLM_MODEL"
set_var PRODUCTION_API_URL "$(terraform -chdir=infra/terraform output -raw api_url)"
set_var ECR_REPOSITORY_URL "$(terraform -chdir=infra/terraform output -raw api_repository_url)"
set_var RELEASE_BUCKET "$(terraform -chdir=infra/terraform output -raw release_bucket)"
set_var BACKUP_BUCKET "$(terraform -chdir=infra/terraform output -raw backup_bucket)"
set_var FRONTEND_BUCKET "$(terraform -chdir=infra/terraform output -raw frontend_bucket)"
set_var EC2_INSTANCE_ID "$(terraform -chdir=infra/terraform output -raw ec2_instance_id)"
set_var CLOUDFRONT_DISTRIBUTION_ID "$(terraform -chdir=infra/terraform output -raw cloudfront_distribution_id)"

stage "Google OAuth callback"
open_url "https://console.cloud.google.com/apis/credentials"
step "Add https://api.$DOMAIN_NAME/api/v1/auth/google/callback as an authorized redirect URI."
step "Add https://app.$DOMAIN_NAME as an authorized JavaScript origin if the Google client asks for one."
pause "Press Enter after saving the OAuth client."
finish
